	zip.Describe("github.com/hanzoai/cloud/apps/team POST /v1/team/channels", zip.Doc{
		Description: "Opens a named channel and answers it as the store now holds it.\n\nIt writes through the SAME applyTx path the Team client uses, so a channel opened\nhere is broadcast to every live client of the space and appears in an open\nsidebar without a reload — the same property listChannels rests on, read from the\nwrite side.\n\nA SIGNED-IN TEAM MEMBER opens it as themselves: they are its first member and\nits owner, every other member named must be somebody the space knows (a person\nin it, or one of the org's agents), and a guest may not open channels at all. An\napplication of the org opens it as the org, with exactly the members it names.\nAnybody else without a team session is 401.\n\nTWO TRANSACTIONS, NOT ONE, when the request states a facet. The document and\nits mixin are separate writes in this model (bindChannel writes only the second),\nand composing them here rather than inventing a combined tx keeps one write\npath for each. A create that lands and a facet that does not is visible as a\nchannel with default intent, which is the honest partial state.",
		Fields: map[string]string{
			"teamChannel.archived":    "Archived reports that the channel has been closed. It is the platform's own\nSpace attribute — the same one the Team client writes — and NOT a field of\nthe work facet, so there is exactly one answer to \"is this channel open\".",
			"teamChannel.bindings":    "Bindings are what this channel is ABOUT, each a \"<kind>:<ref>\" string —\n\"project:acme/web\", \"repo:hanzoai/cloud\", \"issue:1010\". One list rather\nthan one field per kind, because the next thing a channel can be about should\nnot be a schema change; and a bound value is opaque here on purpose, since\nthe app that owns a project is the app that can resolve one. HIP-0523 §2:\na binding is a REFERENCE, never a copy — a channel holding an issue's title or\nstatus would be the parallel work-item store HIP-1160 §1 forbids.",
			"teamChannel.direct":      "Direct reports that this is a channel between people rather than a named\nchannel. It is derived from the document's class, so it cannot disagree\nwith what the client will render.",
			"teamChannel.id":          "ID is the channel document's own id, and the value the bind op addresses.\nIt is unique within a space, not across the org.",
			"teamChannel.kind":        "Kind is what sort of channel this is: \"public\" (open to everyone in the\nspace), \"private\" (open to its members) or \"dm\" (a conversation between\nthe people in it). It is derived from the class and the private flag, so it\ncannot disagree with Direct and Private beside it.",
			"teamChannel.life":        "Life is the channel's lifecycle INTENT — \"standing\" or \"bound\" (HIP-0523 §2).\nAbsent on the document it reads \"standing\": a channel nobody classified is one\nthat persists.",
			"teamChannel.members":     "Members are the account uuids in the channel, agents included: an agent\nprojects as a space member under a uuid derived from its id, so a\ncaller comparing this against GET /v1/bot/members learns which channels an\nagent is in.",
			"teamChannel.name":        "Name is what a person sees in a sidebar. A direct message carries none, so\nthis is empty for one — the members are its name.",
			"teamChannel.private":     "Private reports that the channel is restricted to its members.",
			"teamChannel.space":       "Space is the space uuid holding this channel. It is part of the\nchannel's address: two spaces of one org may each hold a channel with\nthe same name, and only the pair identifies one.",
			"teamChannel.topic":       "Topic is the channel's own one-line subject, as the Team client sets it.",
			"teamChannelNew.bindings": "Bindings are what the channel is about, each \"<kind>:<ref>\".",
			"teamChannelNew.life":     "Life is the lifecycle intent, \"standing\" or \"bound\"; empty reads standing.",
			"teamChannelNew.members":  "Members are the account uuids in the channel. A public channel may open empty —\nanyone in the org can find it — and a private one that names nobody is\nrefused rather than created unreachable.",
			"teamChannelNew.name":     "Name is what a person sees in a sidebar — \"bugfix-1010\", not \"#bugfix-1010\".\nThe sigil is how a client DRAWS a channel, and storing it would put it in the\nname twice the first time a client added its own.",
			"teamChannelNew.private":  "Private restricts the channel to its members. Public is the default because a\nchannel nobody can find is the more surprising of the two.",
			"teamChannelNew.space":    "Space is where the channel is opened. Optional: an org with one space has no\nchoice to make, so it does not have to state one. An org with several must,\nbecause picking for it would make the channel's home depend on iteration order.",
			"teamChannelNew.topic":    "Topic is the channel's one-line subject.",
			"teamChannelOne.channel":  "Channel is the channel as it now stands, in the listing's shape.",
		},
		Example: json.RawMessage(`{"name":"bugfix-1010","life":"bound","bindings":["issue:1010"]}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/team POST /v1/team/channels/:id/members", zip.Doc{
		Description: "Adds people to a channel and answers the channel as it now stands.\n\nAnyone in the space except a guest may join a public channel by naming\nthemselves. Adding somebody else takes being in the channel already (or\nadministering the space, for a channel they can see). A direct message's people\nare what it is, so none can be added — open another one. Everyone added must\nbe a member of the space or one of the org's agents; an agent added to a channel\nanswers when it is @-mentioned there.",
		Fields: map[string]string{
			"teamChannel.archived":    "Archived reports that the channel has been closed. It is the platform's own\nSpace attribute — the same one the Team client writes — and NOT a field of\nthe work facet, so there is exactly one answer to \"is this channel open\".",
			"teamChannel.bindings":    "Bindings are what this channel is ABOUT, each a \"<kind>:<ref>\" string —\n\"project:acme/web\", \"repo:hanzoai/cloud\", \"issue:1010\". One list rather\nthan one field per kind, because the next thing a channel can be about should\nnot be a schema change; and a bound value is opaque here on purpose, since\nthe app that owns a project is the app that can resolve one. HIP-0523 §2:\na binding is a REFERENCE, never a copy — a channel holding an issue's title or\nstatus would be the parallel work-item store HIP-1160 §1 forbids.",
			"teamChannel.direct":      "Direct reports that this is a channel between people rather than a named\nchannel. It is derived from the document's class, so it cannot disagree\nwith what the client will render.",
			"teamChannel.id":          "ID is the channel document's own id, and the value the bind op addresses.\nIt is unique within a space, not across the org.",
			"teamChannel.kind":        "Kind is what sort of channel this is: \"public\" (open to everyone in the\nspace), \"private\" (open to its members) or \"dm\" (a conversation between\nthe people in it). It is derived from the class and the private flag, so it\ncannot disagree with Direct and Private beside it.",
			"teamChannel.life":        "Life is the channel's lifecycle INTENT — \"standing\" or \"bound\" (HIP-0523 §2).\nAbsent on the document it reads \"standing\": a channel nobody classified is one\nthat persists.",
			"teamChannel.members":     "Members are the account uuids in the channel, agents included: an agent\nprojects as a space member under a uuid derived from its id, so a\ncaller comparing this against GET /v1/bot/members learns which channels an\nagent is in.",
			"teamChannel.name":        "Name is what a person sees in a sidebar. A direct message carries none, so\nthis is empty for one — the members are its name.",
			"teamChannel.private":     "Private reports that the channel is restricted to its members.",
			"teamChannel.space":       "Space is the space uuid holding this channel. It is part of the\nchannel's address: two spaces of one org may each hold a channel with\nthe same name, and only the pair identifies one.",
			"teamChannel.topic":       "Topic is the channel's own one-line subject, as the Team client sets it.",
			"teamChannelJoin.id":      "ID is the channel, from the path.",
			"teamChannelJoin.members": "Members are the account uuids to add — people or agents of the space.\nNaming only yourself joins a public channel.",
			"teamChannelJoin.space":   "Space is the space uuid holding it. Body-only.",
			"teamChannelOne.channel":  "Channel is the channel as it now stands, in the listing's shape.",
		},
		Example: json.RawMessage(`{"space":"0e3c…","members":["9f2c…"]}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/team POST /v1/team/channels/:id/messages", zip.Doc{
		Description: "Says one thing in a channel, as the caller.\n\nThe write goes through the SAME applyTx path the Team client's own messages\ntake and is broadcast to every connected client of the space, so a message\nsent here appears live in an open channel rather than on the next reload. It\nanswers the message as the store now HOLDS it.\n\n`<@account-uuid>` in the text is stored as the platform's mention, so the\nperson is notified in their inbox. Mentioning one of the org's agents — or\nwriting in a direct message with one — wakes it: it runs as itself, on behalf\nof the caller, and posts its answer into the same channel. The caller must be\nable to see the channel, and an archived channel refuses new messages (409).",
		Fields: map[string]string{
			"teamFile.file":          "File is the blob id, readable at GET /v1/team/files/{space}/{name}?file={file}.",
			"teamFile.id":            "ID is the attachment document's own id.",
			"teamFile.name":          "Name is the file's name as the person uploaded it.",
			"teamFile.size":          "Size is the file's length in bytes, as the uploader stated it.",
			"teamFile.type":          "Type is the media type the uploader declared. The download route serves\nwhat the BYTES are, not this; it is a hint for drawing an icon.",
			"teamFileIn.file":        "File is the blob id — the uuid the file was uploaded under with\nPOST /v1/team/files/{space}. A blob of another space cannot be named: the\ndownload is keyed by this message's space, so a foreign id resolves to\nnothing.",
			"teamFileIn.name":        "Name is the file's name as a person should see it.",
			"teamFileIn.size":        "Size is the file's length in bytes.",
			"teamFileIn.type":        "Type is the file's media type, e.g. \"image/png\".",
			"teamMessage.author":     "Author is the team account uuid that wrote it. It is an ACCOUNT and not a\ndisplay name: what to call somebody is the roster's answer\n(GET /v1/team/members), and copying it onto every message is how the two\ncome to disagree. An agent's messages carry the account derived from its\nid, so the same field answers for both.",
			"teamMessage.channel":    "Channel is the channel it was said in — the same id the channel listing answers\nwith, so a caller holding a message can name its channel without a second read.\nA reply names the channel its thread is in; a comment on a document has none.",
			"teamMessage.createdOn":  "CreatedOn is unix MILLIseconds, which is what the platform stamps.",
			"teamMessage.doc":        "Doc is the document this message is a comment on. Empty for a message in a\nchannel.",
			"teamMessage.editedOn":   "EditedOn is when the author last edited the message, unix milliseconds.\nAbsent for a message never edited.",
			"teamMessage.files":      "Files are the files attached to the message.",
			"teamMessage.id":         "ID is the message document's own id.",
			"teamMessage.lastReply":  "LastReply is when the thread was last answered, unix milliseconds. Absent\nfor a message with no replies.",
			"teamMessage.mentions":   "Mentions are the account uuids the message @-mentions — exactly the\npeople notify.go told they were mentioned.",
			"teamMessage.reactions":  "Reactions are the emoji people reacted with, one entry per emoji, in the\norder each emoji was first used.",
			"teamMessage.replies":    "Replies is how many replies the message's thread holds.",
			"teamMessage.text":       "Text is the message as PLAIN TEXT. The document stores markup; this is the\nsame `plainText` reduction the agent responder reads a prompt with, so a\ncaller never has to parse the client's markup to know what was said. A\nmention reads as \"@Name\" here and is listed by id in Mentions.",
			"teamMessage.thread":     "Thread is the message this one replies to. Empty for a message that starts\na conversation rather than answering one.",
			"teamMessageWrite.files": "Files attaches blobs already uploaded to the space. A message may be\nfiles alone, with no text.",
			"teamMessageWrite.id":    "ID is the channel to say it in, from the path.",
			"teamMessageWrite.space": "Space names the space holding the channel. Body-only: a query string may not\nredirect a write.",
			"teamMessageWrite.text":  "Text is what to say, as plain text. It is wrapped in the client's markup on\nthe way in, so a caller writes words rather than HTML. `<@account-uuid>`\nmentions a member of the space: it is stored as the platform's mention, so\nthey are notified, and an agent mentioned this way answers.",
			"teamReaction.accounts":  "Accounts are the account uuids that reacted with it, earliest first.",
			"teamReaction.count":     "Count is how many people reacted with it.",
			"teamReaction.emoji":     "Emoji is the reaction itself, as the person picked it.",
		},
		Example: json.RawMessage(`{"space":"0e3c…","text":"deploying now, <@9f2c…> can you watch the dashboards?"}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/team POST /v1/team/collaborator/rpc/:documentId", zip.Doc{
		Description: "CollabRPC is the collaborative-markup snapshot plane the Team front's editor\nspeaks: createContent stores a document field's markup at a fresh, immutable\nblob ref and returns it, updateContent stores a new snapshot and answers\nnothing, and getContent reads back the exact snapshot a ref names.\n\ncreateContent ALSO seeds the live-editing update log from the front-supplied\nY.js update, so a dialog-authored description is visible in the collaborative\neditor — which replays that log — and not only in snapshot reads.\nupdateContent never touches that log: peers may be live-editing the document,\nand their edits are not this call's to overwrite.\n\nEvery call is scoped to the caller's VERIFIED session or space token: the\ndocumentId's space must be the token's space when the token names one,\nand the caller must be a member of it. An unknown space, another tenant's\nspace and a space the caller is not in all answer the same 404, so a\nprobe learns nothing about what exists.",
		Fields: map[string]string{
			"collabPayload.content":    "Content maps a document field to its ProseMirror markup JSON.",
			"collabPayload.source":     "Source is the blob ref a getContent reads the snapshot from. Absent means\nthere is no snapshot to read, which answers empty content.",
			"collabPayload.updates":    "Updates carries, per field, a base64 Y.js state update encoding the SAME\nmarkup — the front computes it (markupToYDoc → encodeStateAsUpdate) so a\ncreateContent seeds the live-editing lane's update log, not just the\nsnapshot blob. Without it a dialog-created description is invisible in the\ncollaborative editor, which replays the ydoc log, never the snapshot.",
			"collabRequest.documentId": "DocumentID addresses the document field, as\n\"<spaceUuid>|<objectClass>|<objectId>|<objectAttr>\" — the\ncollaborator-client encodeDocumentId shape, from the path.",
			"collabRequest.method":     "Method is the verb: createContent, updateContent or getContent.",
			"collabRequest.payload":    "Payload is the verb's argument.",
			"collabResult.content":     "Content maps each document field to its value for the verb: the new blob\nref after a createContent, the stored markup after a getContent.",
			"collabResult.error":       "Error carries a SEMANTIC refusal, which this RPC reports under 200 because\nthe client throws on result.error — auth and tenancy failures are HTTP\nstatuses instead.",
		},
		Example: json.RawMessage(`{"documentId":"6579…|tracker:class:Issue|issue-1|description","method":"getContent","payload":{"source":"issue-1-description-1730000000000"}}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/team POST /v1/team/dms", zip.Doc{
		Description: "Opens the direct message between the caller and the people named,\nor answers the one that already exists — there is one conversation per set of\npeople, however many times it is asked for.\n\nEvery person named must be a member of the space or one of the org's agents;\na direct message with an agent is a conversation it answers every message in,\nand a guest may not open one.\nAnswers 201 when this call opened it and 200 when it was already there.",
		Fields: map[string]string{
			"teamChannel.archived":   "Archived reports that the channel has been closed. It is the platform's own\nSpace attribute — the same one the Team client writes — and NOT a field of\nthe work facet, so there is exactly one answer to \"is this channel open\".",
			"teamChannel.bindings":   "Bindings are what this channel is ABOUT, each a \"<kind>:<ref>\" string —\n\"project:acme/web\", \"repo:hanzoai/cloud\", \"issue:1010\". One list rather\nthan one field per kind, because the next thing a channel can be about should\nnot be a schema change; and a bound value is opaque here on purpose, since\nthe app that owns a project is the app that can resolve one. HIP-0523 §2:\na binding is a REFERENCE, never a copy — a channel holding an issue's title or\nstatus would be the parallel work-item store HIP-1160 §1 forbids.",
			"teamChannel.direct":     "Direct reports that this is a channel between people rather than a named\nchannel. It is derived from the document's class, so it cannot disagree\nwith what the client will render.",
			"teamChannel.id":         "ID is the channel document's own id, and the value the bind op addresses.\nIt is unique within a space, not across the org.",
			"teamChannel.kind":       "Kind is what sort of channel this is: \"public\" (open to everyone in the\nspace), \"private\" (open to its members) or \"dm\" (a conversation between\nthe people in it). It is derived from the class and the private flag, so it\ncannot disagree with Direct and Private beside it.",
			"teamChannel.life":       "Life is the channel's lifecycle INTENT — \"standing\" or \"bound\" (HIP-0523 §2).\nAbsent on the document it reads \"standing\": a channel nobody classified is one\nthat persists.",
			"teamChannel.members":    "Members are the account uuids in the channel, agents included: an agent\nprojects as a space member under a uuid derived from its id, so a\ncaller comparing this against GET /v1/bot/members learns which channels an\nagent is in.",
			"teamChannel.name":       "Name is what a person sees in a sidebar. A direct message carries none, so\nthis is empty for one — the members are its name.",
			"teamChannel.private":    "Private reports that the channel is restricted to its members.",
			"teamChannel.space":      "Space is the space uuid holding this channel. It is part of the\nchannel's address: two spaces of one org may each hold a channel with\nthe same name, and only the pair identifies one.",
			"teamChannel.topic":      "Topic is the channel's own one-line subject, as the Team client sets it.",
			"teamDirect.channel":     "Channel is the direct message, as the channel listing answers it.",
			"teamDirect.created":     "Created is true when this call opened the conversation (201) and false\nwhen it already existed (200).",
			"teamDirectOpen.members": "Members are the account uuids to talk to — people or agents of the space.\nThe caller is always in the conversation and need not name themselves; an\nempty list is the caller's own notes-to-self conversation.",
			"teamDirectOpen.space":   "Space is the space uuid. Optional for a caller in exactly one space.",
		},
		Example: json.RawMessage(`{"members":["9f2c…"]}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/team POST /v1/team/docs", zip.Doc{
		Description: "Creates a document, as the caller, after its siblings.\n\nIt is created through the Team client's own write path, so it appears in an\nopen Documents sidebar live, and its author is subscribed to it: a comment on\nit lands in their inbox. Its body starts empty — open the returned\n`collaborator` id on the /v1/team/collaborator socket to write it.\n\nA space whose caller can write no teamspace at all gets one on its first\ndocument: a public \"General\" teamspace every current member of the space is\nin, which is what the Team client would otherwise make somebody create by hand\nbefore the first page. Guests and agents are not made members of it.",
		Fields: map[string]string{
			"teamDoc.author":       "Author is the account uuid that created it.",
			"teamDoc.collaborator": "Collaborator is the documentId to open the body with on the\n/v1/team/collaborator Y.js socket:\n\"<space>|document:class:Document|<id>|content\".",
			"teamDoc.comments":     "Comments is how many comments it has.",
			"teamDoc.createdOn":    "CreatedOn is when it was created, unix milliseconds.",
			"teamDoc.id":           "ID is the document's own id.",
			"teamDoc.modifiedOn":   "ModifiedOn is when its title or place last changed, unix milliseconds.\nEdits to the body happen on the collaborator socket and do not move it.",
			"teamDoc.parent":       "Parent is the document this one is nested under. Empty for a document at\nthe top of its teamspace.",
			"teamDoc.rank":         "Rank orders siblings: compare as plain strings, ascending.",
			"teamDoc.space":        "Space is the space uuid holding it.",
			"teamDoc.teamspace":    "Teamspace is the teamspace it belongs to.",
			"teamDoc.title":        "Title is the document's title.",
			"teamDocNew.parent":    "Parent nests the new document under another one.",
			"teamDocNew.space":     "Space is the space uuid. Optional for a caller in exactly one space.",
			"teamDocNew.teamspace": "Teamspace is where the document goes. Optional: a document nested under a\nparent goes in the parent's teamspace, and a space with exactly one\nteamspace the caller can write needs no name — with none, the first\ndocument opens a public \"General\" teamspace for the whole space.",
			"teamDocNew.title":     "Title is the document's title. Empty reads \"Untitled\", as in the Team\nclient.",
		},
		Example: json.RawMessage(`{"title":"Runbook","parent":"d41c"}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/team POST /v1/team/docs/:id/comments", zip.Doc{
		Description: "Comments on a document, as the caller.\n\nIt is a message attached to the document, written through the Team client's\nown path: the people subscribed to the document and anyone mentioned are\nnotified, and an agent mentioned answers with a comment of its own. It can be\nreplied to, reacted to, edited and deleted with the message ops.",
		Fields: map[string]string{
			"teamCommentWrite.files": "Files attaches blobs already uploaded to the space.",
			"teamCommentWrite.id":    "ID is the document, from the path.",
			"teamCommentWrite.space": "Space is the space uuid holding it. Body-only.",
			"teamCommentWrite.text":  "Text is the comment, with the same `<@account-uuid>` mentions a message\ntakes.",
			"teamFile.file":          "File is the blob id, readable at GET /v1/team/files/{space}/{name}?file={file}.",
			"teamFile.id":            "ID is the attachment document's own id.",
			"teamFile.name":          "Name is the file's name as the person uploaded it.",
			"teamFile.size":          "Size is the file's length in bytes, as the uploader stated it.",
			"teamFile.type":          "Type is the media type the uploader declared. The download route serves\nwhat the BYTES are, not this; it is a hint for drawing an icon.",
			"teamFileIn.file":        "File is the blob id — the uuid the file was uploaded under with\nPOST /v1/team/files/{space}. A blob of another space cannot be named: the\ndownload is keyed by this message's space, so a foreign id resolves to\nnothing.",
			"teamFileIn.name":        "Name is the file's name as a person should see it.",
			"teamFileIn.size":        "Size is the file's length in bytes.",
			"teamFileIn.type":        "Type is the file's media type, e.g. \"image/png\".",
			"teamMessage.author":     "Author is the team account uuid that wrote it. It is an ACCOUNT and not a\ndisplay name: what to call somebody is the roster's answer\n(GET /v1/team/members), and copying it onto every message is how the two\ncome to disagree. An agent's messages carry the account derived from its\nid, so the same field answers for both.",
			"teamMessage.channel":    "Channel is the channel it was said in — the same id the channel listing answers\nwith, so a caller holding a message can name its channel without a second read.\nA reply names the channel its thread is in; a comment on a document has none.",
			"teamMessage.createdOn":  "CreatedOn is unix MILLIseconds, which is what the platform stamps.",
			"teamMessage.doc":        "Doc is the document this message is a comment on. Empty for a message in a\nchannel.",
			"teamMessage.editedOn":   "EditedOn is when the author last edited the message, unix milliseconds.\nAbsent for a message never edited.",
			"teamMessage.files":      "Files are the files attached to the message.",
			"teamMessage.id":         "ID is the message document's own id.",
			"teamMessage.lastReply":  "LastReply is when the thread was last answered, unix milliseconds. Absent\nfor a message with no replies.",
			"teamMessage.mentions":   "Mentions are the account uuids the message @-mentions — exactly the\npeople notify.go told they were mentioned.",
			"teamMessage.reactions":  "Reactions are the emoji people reacted with, one entry per emoji, in the\norder each emoji was first used.",
			"teamMessage.replies":    "Replies is how many replies the message's thread holds.",
			"teamMessage.text":       "Text is the message as PLAIN TEXT. The document stores markup; this is the\nsame `plainText` reduction the agent responder reads a prompt with, so a\ncaller never has to parse the client's markup to know what was said. A\nmention reads as \"@Name\" here and is listed by id in Mentions.",
			"teamMessage.thread":     "Thread is the message this one replies to. Empty for a message that starts\na conversation rather than answering one.",
			"teamReaction.accounts":  "Accounts are the account uuids that reacted with it, earliest first.",
			"teamReaction.count":     "Count is how many people reacted with it.",
			"teamReaction.emoji":     "Emoji is the reaction itself, as the person picked it.",
		},
		Example: json.RawMessage(`{"space":"0e3c…","text":"step 3 is out of date, <@9f2c…>"}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/team POST /v1/team/files/:space", zip.Doc{
		Description: "Stores the uploaded bytes under the CLIENT-supplied blob uuid (the\nmultipart file's filename). The server does NOT mint the id — the front owns it\n(front.ts: formData.append('file', file, uuid)). Response body is irrelevant\n(uploadFile discards it); we echo the id for curl/debug.",
	})
